import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { canonical } from './model.mjs';
import { fileURLToPath } from 'node:url';
const targets = {
  'packages/test-fixtures/fixtures/fin-002.json':
    JSON.stringify(canonical, null, 2) + '\n',
  'packages/test-fixtures/src/generated/canonical.ts':
    '// Generated by infra/fixtures/generate.mjs. Entirely synthetic FIN-002.\nexport const canonicalFixture = ' +
    JSON.stringify(canonical, null, 2) +
    ' as const;\n',
};
// Use the repository formatter so the generated check compares the checked-in bytes.
import { format, resolveConfig } from 'prettier';
try {
  for (const [name, source] of Object.entries(targets)) {
    const text = await format(source, {
      ...(await resolveConfig(
        fileURLToPath(new URL('../../' + name, import.meta.url)),
      )),
      parser: name.endsWith('.json') ? 'json' : 'typescript',
    });
    const url = new URL('../../' + name, import.meta.url);
    if (process.argv.includes('--check')) {
      if (readFileSync(url, 'utf8') !== text)
        throw Error('FIXTURE_GENERATION_MISMATCH');
    } else {
      mkdirSync(new URL('.', url), { recursive: true });
      writeFileSync(url, text);
    }
  }
  console.log('FIN-002 fixture generation OK.');
} catch {
  console.error('FIXTURE_GENERATION_FAILED');
  process.exitCode = 1;
}
